 WHERE p.`slug` = 'privacy' AND bt.`locale` = 'bn'
   AND LOCATE('<li>ইমেইল সাবস্ক্রিপশন — শুধু ঠিকানা: আপনি বাদ দিতে না বলা পর্যন্ত।</li>', JSON_UNQUOTE(JSON_EXTRACT(bt.`data`, '$.body'))) > 0;
UPDATE `block_translations` bt JOIN `blocks` b ON b.`id` = bt.`block_id` JOIN `pages` p ON p.`id` = b.`page_id`
   SET bt.`data` = JSON_SET(bt.`data`, '$.body', REPLACE(JSON_UNQUOTE(JSON_EXTRACT(bt.`data`, '$.body')), '<li>邮件订阅——仅邮箱地址：直至您退订或要求删除。</li>', '<li>邮件订阅——仅邮箱地址：直至您退订或要求删除。</li><li>道路提醒订阅——您的手机号码及所选渠道（短信或 WhatsApp）：直至您退订。</li>'))
 WHERE p.`slug` = 'privacy' AND bt.`locale` = 'zh'
   AND LOCATE('<li>邮件订阅——仅邮箱地址：直至您退订或要求删除。</li>', JSON_UNQUOTE(JSON_EXTRACT(bt.`data`, '$.body'))) > 0;

-- C10: Chinese pages do load a font (self-hosted Noto Sans SC).
UPDATE `block_translations` bt JOIN `blocks` b ON b.`id` = bt.`block_id` JOIN `pages` p ON p.`id` = b.`page_id`
   SET bt.`data` = JSON_SET(bt.`data`, '$.body', REPLACE(JSON_UNQUOTE(JSON_EXTRACT(bt.`data`, '$.body')), '<p><strong>Chinese pages have no supplied font.</strong> The site ships Latin and Bengali web fonts but no Chinese one, so a reader on a device without a Chinese font installed may see empty boxes instead of characters.</p>', '<p><strong>Chinese text loads in parts.</strong> Chinese pages use a self-hosted Noto Sans SC font that downloads in pieces, so on a slow connection some characters may first appear in your device’s own font.</p>'))
 WHERE p.`slug` = 'accessibility' AND bt.`locale` = 'en'
   AND LOCATE('<p><strong>Chinese pages have no supplied font.</strong> The site ships Latin and Bengali web fonts but no Chinese one, so a reader on a device without a Chinese font installed may see empty boxes instead of characters.</p>', JSON_UNQUOTE(JSON_EXTRACT(bt.`data`, '$.body'))) > 0;
UPDATE `block_translations` bt JOIN `blocks` b ON b.`id` = bt.`block_id` JOIN `pages` p ON p.`id` = b.`page_id`
   SET bt.`data` = JSON_SET(bt.`data`, '$.body', REPLACE(JSON_UNQUOTE(JSON_EXTRACT(bt.`data`, '$.body')), '<p><strong>চীনা পৃষ্ঠার জন্য কোনও ফন্ট সরবরাহ করা হয় না।</strong> সাইটটি ল্যাটিন ও বাংলা ওয়েব ফন্ট সরবরাহ করে, চীনা নয় — তাই যে ডিভাইসে চীনা ফন্ট ইনস্টল করা নেই সেখানে অক্ষরের বদলে খালি বাক্স দেখা যেতে পারে।</p>', '<p><strong>চীনা লেখা ধাপে ধাপে লোড হয়।</strong> চীনা পেজে সাইটের নিজস্ব Noto Sans SC ফন্ট টুকরো টুকরো ডাউনলোড হয়, তাই ধীর ইন্টারনেটে কিছু অক্ষর প্রথমে আপনার ডিভাইসের নিজের ফন্টে দেখা যেতে পারে।</p>'))
 WHERE p.`slug` = 'accessibility' AND bt.`locale` = 'bn'
   AND LOCATE('<p><strong>চীনা পৃষ্ঠার জন্য কোনও ফন্ট সরবরাহ করা হয় না।</strong> সাইটটি ল্যাটিন ও বাংলা ওয়েব ফন্ট সরবরাহ করে, চীনা নয় — তাই যে ডিভাইসে চীনা ফন্ট ইনস্টল করা নেই সেখানে অক্ষরের বদলে খালি বাক্স দেখা যেতে পারে।</p>', JSON_UNQUOTE(JSON_EXTRACT(bt.`data`, '$.body'))) > 0;
UPDATE `block_translations` bt JOIN `blocks` b ON b.`id` = bt.`block_id` JOIN `pages` p ON p.`id` = b.`page_id`
   SET bt.`data` = JSON_SET(bt.`data`, '$.body', REPLACE(JSON_UNQUOTE(JSON_EXTRACT(bt.`data`, '$.body')), '<p><strong>中文页面未附带字体。</strong>本站提供拉丁文与孟加拉文网页字体，但未提供中文字体，因此未安装中文字体的设备可能显示空白方框而非文字。</p>', '<p><strong>中文字体分段加载。</strong>中文页面使用本站自托管的 Noto Sans SC 字体，按需分段下载；网络较慢时，部分文字可能先以设备自带字体显示。</p>'))
 WHERE p.`slug` = 'accessibility' AND bt.`locale` = 'zh'
   AND LOCATE('<p><strong>中文页面未附带字体。</strong>本站提供拉丁文与孟加拉文网页字体，但未提供中文字体，因此未安装中文字体的设备可能显示空白方框而非文字。</p>', JSON_UNQUOTE(JSON_EXTRACT(bt.`data`, '$.body'))) > 0;

-- T3: the Bangla home page says what the English says.
UPDATE `block_translations` bt JOIN `blocks` b ON b.`id` = bt.`block_id` JOIN `pages` p ON p.`id` = b.`page_id`
   SET bt.`data` = JSON_SET(bt.`data`, '$.body', REPLACE(JSON_UNQUOTE(JSON_EXTRACT(bt.`data`, '$.body')), 'এবং এ কারণেই শহরের ভেতর দিয়ে যে যাত্রায় দুই ঘণ্টা লাগে, সম্পূর্ণ করিডোর খুলে গেলে তা তার সামান্য সময়েই শেষ হওয়ার কথা।', 'এবং সে কারণেই পুরো করিডোর খুলে গেলে যে যাত্রা এখন শহরের ভেতর দিয়ে যায়, তা শহরকে পুরোপুরি এড়িয়ে যাবে।'))
 WHERE p.`slug` = 'home' AND bt.`locale` = 'bn'
   AND LOCATE('এবং এ কারণেই শহরের ভেতর দিয়ে যে যাত্রায় দুই ঘণ্টা লাগে, সম্পূর্ণ করিডোর খুলে গেলে তা তার সামান্য সময়েই শেষ হওয়ার কথা।', JSON_UNQUOTE(JSON_EXTRACT(bt.`data`, '$.body'))) > 0;

-- T4: "মি." reads as metres.
UPDATE `block_translations` bt JOIN `blocks` b ON b.`id` = bt.`block_id` JOIN `pages` p ON p.`id` = b.`page_id`
   SET bt.`data` = REPLACE(CAST(bt.`data` AS CHAR), '"unit":"মি."', '"unit":"মিলিয়ন ডলার"')
 WHERE bt.`locale` = 'bn'
   AND LOCATE('"unit":"মি."', CAST(bt.`data` AS CHAR)) > 0;
