   SET bt.`data` = REPLACE(CAST(bt.`data` AS CHAR), '"unit": "মি."', '"unit": "মিলিয়ন ডলার"')
 WHERE bt.`locale` = 'bn'
   AND LOCATE('"unit": "মি."', CAST(bt.`data` AS CHAR)) > 0;
